package commands

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"

	"github.com/belluikit/bellui"
	"github.com/urfave/cli/v2"
)

const fileHeader = "// auto-generated\n" + // to exclude this file in goreportcard (it has to be first)
	"// Code generated by '$ bellui bundle'. DO NOT EDIT." // idiomatic mark, see https://golang.org/s/generatedcode

var filenameRegex = regexp.MustCompile("[^a-zA-Z0-9]+")

// Bundle returns the vendor cli command
func Bundle() *cli.Command {
	b := &Bundler{}

	return &cli.Command{
		Name:        "bundle",
		Usage:       "Embeds static content into your go application",
		ArgsUsage:   "file ...",
		Description: "Each resource will have a generated filename unless specified.",
		Flags: []cli.Flag{
			&cli.StringFlag{
				Name:        "name",
				Usage:       "set variable name to assign the resource (file mode only)",
				Destination: &b.name,
			},
			&cli.StringFlag{
				Name:        "output",
				Aliases:     []string{"o"},
				Usage:       "specify output file (instead of standard output)",
				Destination: &b.out,
			},
			&cli.StringFlag{
				Name:        "package",
				Aliases:     []string{"pkg"},
				Usage:       "set package to output in headers when not appending",
				Value:       "main",
				Destination: &b.pkg,
			},
			&cli.StringFlag{
				Name:        "prefix",
				Usage:       "specify prefix for variables, ignored if name is set",
				Value:       "resource",
				Destination: &b.prefix,
			},
			&cli.BoolFlag{
				Name:        "append",
				Aliases:     []string{"a"},
				Usage:       "append an existing go file, and don't output headers",
				Destination: &b.noheader,
			},
		},
		Action: b.bundleAction,
	}
}

// Bundler bundles resources into Go code.
type Bundler struct {
	name, pkg, out string
	prefix         string
	noheader       bool
}

func (b *Bundler) bundleAction(ctx *cli.Context) (err error) {
	if ctx.Args().Len() < 1 {
		return errors.New("missing required file or directory parameter after flags")
	}

	outFile := os.Stdout
	if b.out != "" {
		file, closeFile, err := openOutputFile(b.out, b.noheader)
		if err != nil {
			return err
		}
		defer func() {
			if r := closeFile(); r != nil {
				err = r
			}
		}()
		outFile = file
	}

	for _, arg := range ctx.Args().Slice() {
		files, err := filepath.Glob(arg)
		if err != nil {
			bellui.LogError("Specified file could not be found", err)
			return err
		}
		for _, file := range files {
			switch stat, err := os.Stat(file); {
			case os.IsNotExist(err):
				bellui.LogError("Specified file could not be found", err)
				return err
			case stat.IsDir():
				return b.dirBundle(file, outFile)
			case b.name != "":
				b.prefix = ""
				fallthrough
			default:
				b.doBundle(file, outFile)
			}
		}
	}

	return nil
}

func (b *Bundler) dirBundle(dirpath string, out *os.File) error {
	files, err := os.ReadDir(dirpath)
	if err != nil {
		bellui.LogError("Error reading specified directory", err)
		return err
	}

	for i, file := range files {
		filename := file.Name()
		if filepath.Ext(filename) == ".go" {
			continue
		}

		b.name = ""

		b.doBundle(filepath.Join(dirpath, filename), out)
		if i == 0 { // only show header on first iteration
			b.noheader = true
		}
	}

	return nil
}

// Bundle takes a file (at filepath) and serialises it into Go to be output into
// a generated bundle file. The go file will be part of the specified package
// (pkg) and the data will be assigned to variable named "name". If you are
// appending an existing resource file then pass true to noheader as the headers
// should only be output once per file.
func (b *Bundler) doBundle(path string, out *os.File) {
	if !b.noheader {
		writeHeader(b.pkg, out)
		b.noheader = true
	}

	name := b.name
	if name == "" {
		name = sanitiseName(filepath.Base(path), b.prefix)
	}
	writeResource(path, name, out)
}

func openOutputFile(filePath string, noheader bool) (file *os.File, close func() error, err error) {
	fileModes := os.O_RDWR | os.O_CREATE | os.O_TRUNC
	if noheader {
		fileModes = os.O_RDWR | os.O_APPEND
	}

	f, err := os.OpenFile(filePath, fileModes, 0o666)
	if err != nil {
		if !os.IsNotExist(err) {
			bellui.LogError("Unable to open output file", err)
			return nil, nil, err
		}

		// try creating the file
		f, err = os.Create(filePath)
		if err != nil {
			bellui.LogError("Unable to read, or create, output file : "+filePath, err)
			return nil, nil, err
		}
	}

	return f, f.Close, nil
}

func sanitiseName(file, prefix string) string {
	titled := strings.Title(file) //lint:ignore SA1019 It is fine for our uses.
	name := filenameRegex.ReplaceAllString(titled, "")

	return prefix + name
}

func writeHeader(pkg string, out *os.File) {
	out.WriteString(fileHeader)
	out.WriteString("\n\npackage ")
	out.WriteString(pkg)
	out.WriteString("\n\nimport (\n")
	out.WriteString("\t_ \"embed\"\n\n")
	out.WriteString("\t\"github.com/belluikit/bellui\"\n")
	out.WriteString(")\n")
}

func writeResource(file, name string, f *os.File) {
	_, err := fmt.Fprintf(f, "\n//go:embed %s\nvar %sData []byte\n", file, name)
	if err != nil {
		bellui.LogError("Unable to write to bundled file", err)
	}

	const format = "var %s = &bellui.StaticResource{\n\tStaticName:    %q,\n\tStaticContent: %sData,\n}\n"
	_, err = fmt.Fprintf(f, format, name, file, name)
	if err != nil {
		bellui.LogError("Unable to write to bundled file", err)
	}
}
